import React from 'react';

const Therapy = () => {
  return (
    <div style={{ padding: '1.5rem' }}>
      <h1 style={{ fontSize: '1.6rem', fontWeight: 700, marginBottom: '0.5rem' }}>Therapy Services</h1>
      <p style={{ color: '#4b5563', marginBottom: '1rem' }}>Overview of therapy attendance and service coverage.</p>
      <div style={{ display: 'grid', gap: '1rem', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))' }}>
        <div style={{ background: '#fff', borderRadius: '12px', padding: '1rem', boxShadow: '0 4px 12px rgba(0,0,0,0.08)' }}>
          <h3 style={{ margin: '0 0 0.25rem' }}>Active Cases</h3>
          <p style={{ fontSize: '1.5rem', fontWeight: 700, margin: 0 }}>41</p>
        </div>
        <div style={{ background: '#fff', borderRadius: '12px', padding: '1rem', boxShadow: '0 4px 12px rgba(0,0,0,0.08)' }}>
          <h3 style={{ margin: '0 0 0.25rem' }}>Sessions This Week</h3>
          <p style={{ fontSize: '1.5rem', fontWeight: 700, margin: 0 }}>26</p>
        </div>
      </div>
    </div>
  );
};

export default Therapy;
